def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []

    # Each candidate groups colored cells by the stripe direction's key.
    for kind in ("row", "diag", "anti"):
        groups = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == 0:
                    continue
                key = r if kind == "row" else (c - r if kind == "diag" else r + c)
                groups.setdefault(key, set()).add(color)
        if groups and all(len(colors) == 1 for colors in groups.values()):
            candidates.append((len(groups), kind, groups))

    _, kind, groups = min(candidates, key=lambda x: x[0])
    period = len(groups)
    mapping = {key % period: next(iter(colors)) for key, colors in groups.items()}

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            key = r if kind == "row" else (c - r if kind == "diag" else r + c)
            row.append(mapping[key % period])
        out.append(row)
    return out
